    // All subset sums of the left half, sorted for lookup.
    vector<long long> left{0};
    for (int i = 0; i < mid; i++) {
        size_t size = left.size();
        for (size_t j = 0; j < size; j++) left.push_back(left[j] + values[i]);
    }
    sort(left.begin(), left.end());
    vector<long long> right(values.begin() + mid, values.end());
    // Walk the right half in Gray-code order: one element toggles per step.
    long long total = 0, previous = 0;
    for (long long mask = 0; mask < (1LL << right.size()); mask++) {
        long long gray = mask ^ (mask >> 1);
        if (mask) {
            long long changed = gray ^ previous;
            int bit = __builtin_ctzll(changed);
            total += (gray & changed) ? right[bit] : -right[bit];
        }
        if (binary_search(left.begin(), left.end(), target - total)) {
            cout << 1 << "\n";
            return 0;
        }
        previous = gray;
    }
    cout << 0 << "\n";
