import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String first = next();
        if (first.isEmpty()) {
            System.out.println(0);
            return;
        }
        int n = Integer.parseInt(first);
        long target = nextLong();
        long[] values = new long[n];
        for (int i = 0; i < n; i++) values[i] = nextLong();
        int mid = n / 2;
        // All subset sums of the left half, sorted for lookup.
        long[] left = new long[1 << mid];
        int size = 1;
        for (int i = 0; i < mid; i++) {
            for (int j = 0; j < size; j++) left[size + j] = left[j] + values[i];
            size *= 2;
        }
        Arrays.sort(left);
        int r = n - mid;
        // Walk the right half in Gray-code order: one element toggles per step.
        long total = 0, previous = 0;
        for (long mask = 0; mask < (1L << r); mask++) {
            long gray = mask ^ (mask >> 1);
            if (mask > 0) {
                long changed = gray ^ previous;
                int bit = Long.numberOfTrailingZeros(changed);
                total += (gray & changed) != 0 ? values[mid + bit] : -values[mid + bit];
            }
            if (Arrays.binarySearch(left, target - total) >= 0) {
                System.out.println(1);
                return;
            }
            previous = gray;
        }
        System.out.println(0);
    }
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"math/bits"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	if len(bytes.TrimSpace(data)) == 0 {
		fmt.Println(0)
		return
	}
	n, target := nextInt(), nextInt()
	values := make([]int, n)
	for i := range values {
		values[i] = nextInt()
	}
	mid := n / 2
	// All subset sums of the left half, sorted for lookup.
	left := []int{0}
	for i := 0; i < mid; i++ {
		size := len(left)
		for j := 0; j < size; j++ {
			left = append(left, left[j]+values[i])
		}
	}
	sort.Ints(left)
	right := values[mid:]
	// Walk the right half in Gray-code order: one element toggles per step.
	total, previous := 0, 0
	for mask := 0; mask < 1<<len(right); mask++ {
		gray := mask ^ (mask >> 1)
		if mask > 0 {
			changed := gray ^ previous
			bit := bits.TrailingZeros(uint(changed))
			if gray&changed != 0 {
				total += right[bit]
			} else {
				total -= right[bit]
			}
		}
		want := target - total
		if k := sort.SearchInts(left, want); k < len(left) && left[k] == want {
			fmt.Println(1)
			return
		}
		previous = gray
	}
	fmt.Println(0)
}
